  "implementation": "def solve(case):
    # Validate case structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    required_keys = ['capacity', 'trials']
    for key in required_keys:
        if key not in case:
            raise ValueError(f"Missing required key: {key}")
    capacity = case['capacity']
    trials = case['trials']
    if not isinstance(capacity, int) or capacity < 0:
        raise ValueError("capacity must be non-negative integer")
    if not isinstance(trials, list):
        raise ValueError("trials must be a list")
    for trial in trials:
        if not isinstance(trial, dict):
            raise ValueError("each trial must be a dict")
        for field in ['signature', 'reflection', 'success']:
            if field not in trial:
                raise ValueError(f"Missing field {field} in trial")
        if not isinstance(trial['signature'], str):
            raise ValueError("signature must be string")
        if not isinstance(trial['reflection'], str):
            raise ValueError("reflection must be string")
        if not isinstance(trial['success'], bool):
            raise ValueError("success must be boolean")

    memory = []
    for i, trial in enumerate(trials):
        if trial['success'] == False:
            replaced = False
            for mem_entry in memory:
                if mem_entry['success'] == False and mem_entry['signature'] == trial['signature']:
                    mem_entry['last_trial'] = i
                    mem_entry['reflection'] = trial['reflection']
                    replaced = True
                    break
            if not replaced:
                memory.append({
                    'last_trial': i,
                    'reflection': trial['reflection'],
                    'signature': trial['signature'],
                    'success': False
                })
        else: # success
            memory.append({
                'last_trial': i,
                'reflection': trial['reflection'],
                'signature': trial['signature'],
                'success': True
            })

    if len(memory) > capacity:
        # sort priority: failures first (success==False), then recency descending, then signature
        memory.sort(key=lambda e: (e['success'] is True, -e['last_trial'], e['signature']))
        memory = memory[:capacity]

    # restore chronological order
    memory.sort(key=lambda e: e['last_trial'])

    signatures = [e['signature'] for e in memory]

    return {'memory': memory, 'signatures': signatures}
